mapper.select:
/* 1:1 문의 목록 조회 */ SELECT I.OTO_INQRY_SN , I.INQRY_TYPE_CD , T.COM_CD_NM AS INQRY_TYPE_CD_NM , I.INQRY_TTL , I.INQRY_PRCS_STTS_CD , S.COM_CD_NM AS INQRY_PRCS_STTS_CD_NM , I.REG_DT FROM OTO_INQRY I LEFT JOIN COM_CD T ON T.COM_CD = I.INQRY_TYPE_CD LEFT JOIN COM_CD S ON S.COM_CD = I.INQRY_PRCS_STTS_CD WHERE I.MBR_SN = #{mbrSn} AND I.DEL_YN = 'N'
AND I.INQRY_PRCS_STTS_CD = #{inqryPrcsSttsCd}
ORDER BY I.REG_DT DESC , I.OTO_INQRY_SN DESC

/* 공통코드명 조회 */
SELECT COM_CD_NM
  FROM COM_CD
 WHERE COM_CD = #{comCd}
 LIMIT 1

mapper.insert:
/* 1:1 문의 등록 */
INSERT INTO OTO_INQRY
     ( MBR_SN
     , PIXEL_CHAR_SN
     , CHAR_PHOTO_SN
     , INQRY_TYPE_CD
     , INQRY_PRCS_STTS_CD
     , INQRY_TTL
     , INQRY_CN
     , REG_DT
     , MDFCN_DT )
VALUES
     ( #{mbrSn}
     , #{pixelCharSn}
     , #{charPhotoSn}
     , #{inqryTypeCd}
     , #{inqryPrcsSttsCd}
     , #{inqryTtl}
     , #{inqryCn}
     , NOW()
     , NOW() )

/* 1:1 문의 상태 변경 이력 등록 */
INSERT INTO OTO_INQRY_STTS_HSTRY
     ( OTO_INQRY_SN
     , MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , CHG_RSN
     , REG_DT )
VALUES
     ( #{otoInqrySn}
     , #{mbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , #{chgRsn}
     , NOW() )

mapper.update:
/* 1:1 문의 수정 */
UPDATE OTO_INQRY

    INQRY_TYPE_CD = #{inqryTypeCd},
    INQRY_TTL = #{inqryTtl},
    INQRY_CN = #{inqryCn},
    MDFCN_DT = NOW()

 WHERE OTO_INQRY_SN = #{otoInqrySn}
   AND INQRY_PRCS_STTS_CD = #{receivedCd}
   AND DEL_YN = 'N'

/* 1:1 문의 삭제 처리 */
UPDATE OTO_INQRY
   SET DEL_YN = 'Y'
     , MDFCN_DT = NOW()
 WHERE OTO_INQRY_SN = #{otoInqrySn}
   AND INQRY_PRCS_STTS_CD = #{receivedCd}
   AND DEL_YN = 'N'

/* 문의 첨부 사진 전체 삭제 처리 */
UPDATE INQRY_ATCH_PHOTO
   SET DEL_YN = 'Y'
     , MDFCN_DT = NOW()
 WHERE OTO_INQRY_SN = #{otoInqrySn}
   AND DEL_YN = 'N'

/* 문의 첨부 사진 삭제 처리 */
UPDATE INQRY_ATCH_PHOTO
   SET DEL_YN = 'Y'
     , MDFCN_DT = NOW()
 WHERE OTO_INQRY_SN = #{otoInqrySn}
   AND DEL_YN = 'N'
   AND ATCH_FILE_SN IN

       #{atchFileSn}

/* 1:1 문의 답변 등록 */
UPDATE OTO_INQRY
   SET PRCS_MBR_SN = #{prcsMbrSn}
     , INQRY_PRCS_STTS_CD = #{answeredCd}
     , ANS_CN = #{ansCn}
     , ANS_DT = NOW()
     , MDFCN_DT = NOW()
 WHERE OTO_INQRY_SN = #{otoInqrySn}
   AND INQRY_PRCS_STTS_CD = #{receivedCd}
   AND DEL_YN = 'N'

mapper.select:
/* 관리자 1:1 문의 목록 조회 */ SELECT I.OTO_INQRY_SN , I.INQRY_TYPE_CD , T.COM_CD_NM AS INQRY_TYPE_CD_NM , I.INQRY_TTL , I.MBR_SN , M.MBR_NCNM , I.INQRY_PRCS_STTS_CD , S.COM_CD_NM AS INQRY_PRCS_STTS_CD_NM , I.REG_DT , CASE WHEN I.DEL_YN = 'Y' THEN TRUE ELSE FALSE END AS DEL_YN FROM OTO_INQRY I LEFT JOIN MBR M ON M.MBR_SN = I.MBR_SN LEFT JOIN COM_CD T ON T.COM_CD = I.INQRY_TYPE_CD LEFT JOIN COM_CD S ON S.COM_CD = I.INQRY_PRCS_STTS_CD
AND I.DEL_YN = 'N'
AND I.INQRY_TYPE_CD = #{cond.inqryTypeCd}
AND I.INQRY_TYPE_CD IN
#{inqryTypeCd}
AND I.INQRY_PRCS_STTS_CD = #{cond.inqryPrcsSttsCd}
AND I.REG_DT >= #{cond.bgngYmd}
AND I.REG_DT < DATE_ADD(#{cond.endYmd}, INTERVAL 1 DAY)
ORDER BY I.REG_DT DESC , I.OTO_INQRY_SN DESC

/* 회원 닉네임 조회 */
SELECT MBR_NCNM
  FROM MBR
 WHERE MBR_SN = #{mbrSn}

mapper.update:
/* 1:1 문의 답변 내용 수정 */
UPDATE OTO_INQRY
   SET ANS_CN = #{ansCn}
     , MDFCN_DT = NOW()
 WHERE OTO_INQRY_SN = #{otoInqrySn}
   AND INQRY_PRCS_STTS_CD = #{answeredCd}
   AND DEL_YN = 'N'

/* 캐릭터 오류 처리 결과 기록 */
UPDATE OTO_INQRY
   SET CHAR_ERR_PRCS_RSLT_CD = #{charErrPrcsRsltCd}
     , MDFCN_DT = NOW()
 WHERE OTO_INQRY_SN = #{otoInqrySn}
   AND CHAR_ERR_PRCS_RSLT_CD IS NULL
   AND DEL_YN = 'N'

mapper.select:
/* 처리 상태별 문의 수 : 유형은 선택 */
SELECT COUNT(*)
  FROM OTO_INQRY I
 WHERE I.DEL_YN = 'N'
   AND I.INQRY_PRCS_STTS_CD = #{inqryPrcsSttsCd}

   AND I.INQRY_TYPE_CD = #{inqryTypeCd}
